import sys
import os
import argparse
import traceback

def parse_args():
    parser = argparse.ArgumentParser(description='Iterative RPE reconstruction with SIRF.')
    parser.add_argument('--raw-data-file', type=str, default=None, help='Raw k-space data file (HDF5).')
    parser.add_argument('--data-path', type=str, default=None, help='Path to data files.')
    parser.add_argument('--output-file', type=str, default='simulated_data.h5', help='Output file for simulated data.')
    parser.add_argument('--engine', type=str, default='Gadgetron', choices=['Gadgetron', 'GadgetronNonCartesian', 'GadgetronParallelproj'], help='Reconstruction engine.')
    parser.add_argument('--run-recon', action='store_true', help='Run reconstruction if non-cartesian code was compiled.')
    parser.add_argument('--trajectory', type=str, default='radial', choices=['cartesian', 'radial', 'goldenangle', 'grpe'], help='Trajectory type.')
    parser.add_argument('--show-plots', action='store_true', help='Show plots.')
    return parser.parse_args()

def import_engine(engine):
    if engine == 'Gadgetron':
        import sirf.Gadgetron as engine_module
    elif engine == 'GadgetronNonCartesian':
        import sirf.GadgetronNonCartesian as engine_module
    elif engine == 'GadgetronParallelproj':
        import sirf.GadgetronParallelproj as engine_module
    else:
        raise ValueError(f"Unknown engine: {engine}")
    return engine_module

def cg_reconstruction(acq_data, engine_module, trajectory_type, show_plots=False):
    # Compute coil sensitivity maps
    csms = engine_module.CoilSensitivityData()
    csms.calculate(acq_data)
    # Set up acquisition model
    acq_model = engine_module.AcquisitionModel(acq_data, csms)
    # Set trajectory
    if trajectory_type == 'radial':
        acq_data.set_radial2D_trajectory()
    elif trajectory_type == 'cartesian':
        acq_data.set_data_trajectory('cartesian')
    elif trajectory_type == 'goldenangle':
        acq_data.set_goldenangle2D_trajectory()
    elif trajectory_type == 'grpe':
        acq_data.set_grpe_trajectory()
    else:
        raise ValueError(f"Unknown trajectory type: {trajectory_type}")
    acq_model.set_coil_sensitivity_maps(csms)
    # Backward projection (adjoint)
    initial_image = acq_model.backward(acq_data)
    # Define symmetric operator for CG
    class SymmetricOperator:
        def __init__(self, acq_model):
            self.acq_model = acq_model
        def apply(self, x):
            return self.acq_model.backward(self.acq_model.forward(x))
    sym_op = SymmetricOperator(acq_model)
    # CG iterations
    def cg(A, b, x0, niter=10):
        x = x0.clone()
        r = b - A.apply(x)
        p = r.clone()
        rsold = r.squared_norm()
        for i in range(niter):
            Ap = A.apply(p)
            alpha = rsold / (p.dot(Ap) + 1e-10)
            x = x + p * alpha
            r = r - Ap * alpha
            rsnew = r.squared_norm()
            if rsnew.sqrt().value < 1e-6:
                break
            p = r + p * (rsnew / rsold)
            rsold = rsnew
        return x
    b = acq_model.backward(acq_data)
    x0 = initial_image
    recon_image = cg(sym_op, b, x0, niter=15)
    if show_plots:
        try:
            import matplotlib.pyplot as plt
            arr = recon_image.as_array()
            plt.imshow(abs(arr[arr.shape[0]//2, :, :]), cmap='gray')
            plt.title('Reconstructed Image (mid-slice)')
            plt.show()
        except Exception:
            pass
    return recon_image

def main():
    args = parse_args()
    try:
        engine_module = import_engine(args.engine)
        # Locate raw data file
        if args.raw_data_file is not None:
            raw_data_file = args.raw_data_file
        else:
            if args.data_path is not None:
                raw_data_file = os.path.join(args.data_path, 'meas_MID00024_FID188687_rpe.h5')
            else:
                try:
                    from sirf.Utilities import examples_data_path
                    raw_data_file = os.path.join(examples_data_path('MR'), 'meas_MID00024_FID188687_rpe.h5')
                except Exception:
                    raise RuntimeError("Could not locate raw data file. Please specify with --raw-data-file.")
        if not os.path.isfile(raw_data_file):
            raise FileNotFoundError(f"Raw data file not found: {raw_data_file}")
        # Read acquisition data
        acq_data = engine_module.AcquisitionData(raw_data_file)
        # Preprocess acquisition data
        processed_acq_data = engine_module.preprocess_acquisition_data(acq_data)
        # Set trajectory
        if args.trajectory == 'radial':
            processed_acq_data.set_radial2D_trajectory()
        elif args.trajectory == 'cartesian':
            processed_acq_data.set_data_trajectory('cartesian')
        elif args.trajectory == 'goldenangle':
            processed_acq_data.set_goldenangle2D_trajectory()
        elif args.trajectory == 'grpe':
            processed_acq_data.set_grpe_trajectory()
        else:
            raise ValueError(f"Unknown trajectory type: {args.trajectory}")
        # Sort processed acquisition data
        processed_acq_data.sort()
        # Save simulated data if requested
        if args.output_file:
            processed_acq_data.write(args.output_file)
        # Perform reconstruction if requested
        if args.run_recon:
            recon_image = cg_reconstruction(processed_acq_data, engine_module, args.trajectory, show_plots=args.show_plots)
            print("Reconstruction complete.")
    except Exception as e:
        print("An error occurred during execution:")
        print(str(e))
        traceback.print_exc()
        sys.exit(1)

if __name__ == '__main__':
    main()
